WITH RECURSIVE x6 AS (SELECT 0 UNION ALL SELECT x5.1 + 1 FROM x8 WHERE x5.1 < 100) SELECT x5.1, x5.v68271, ST_ASTEXT(ST_UNION(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(GEOMETRYCOLLECTION())'), ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(GEOMETRYCOLLECTION(POINT(1 1), GEOMETRYCOLLECTION(GEOMETRYCOLLECTION())))'))) AS x3, x5.1 FROM v68270 AS x5 WHERE x5.v68271 ->> '$.name' = 'James'